-- =====================================================================
-- khaustan_menu_data_HotelSunlight_400070012_KhaustanRestaurantMenu.sql
--
-- RESTAURANT : Hotel Sunlight Restaurant & Guest House
--              304, Lal Bahadur Shastri Marg, Kurla West, Kurla, Mumbai, Maharashtra 400070
-- IDS        : establishment_id = restaurant_id = source_id = 400070012 (given directly in the JSON)
-- SOURCE     : Hotel_Sunlight_Menu_OCR.json (OCR JSON, 12 menu-page images)
-- TARGET     : PostgreSQL, database "KhaustanRestaurantMenu" (one transaction)
-- SCHEMA REF : khaustan-KhaustanRestaurantMenu-Create_DB-postgresql.sql
-- LOOKUP REF : khaustan_lookup_data_seed_KhaustanRestaurantMenu.sql (READ-ONLY - see below)
-- NOT FROM A BRAND: no brand row is created or referenced, per instruction.
--
-- HOW TO RUN  psql -v ON_ERROR_STOP=1 -f <this file>
--             Run it once in a disposable/staging database first. It could not be executed
--             against PostgreSQL where it was produced.
--
-- LOOKUP TABLES ARE READ-ONLY IN THIS SCRIPT. It never inserts, updates or deletes a
-- protein_type or platform_tag row - it only reads them by code. The pre-flight check aborts
-- before writing anything if a row it needs is missing.
--
-- ID SCHEME: establishment_id = restaurant_id = source_id = 400070012. menu_board, menu_category,
-- menu_item, menu_item_variant, menu_item_price and menu_board_item each use their OWN counter,
-- starting at 400070012001 = 400070012*1000+1 and incrementing by 1 in source order within that
-- table. menu_item_availability is declared in the same scheme but is not used here - nothing
-- on this menu ties a specific dish to a specific day or time window (see note 9).
-- restaurant_phone_id, restaurant_hours_id, restaurant_tag_id, canonical_dish(_id/_name) use
-- the schema's ordinary application-generated approach (one helper sequence).
--
-- ROWS LOADED
--   establishment 1 | restaurant 1 | restaurant_phone 4 | restaurant_hours 7
--   restaurant_delivery 1 | restaurant_tag 4 | source_record 1 | menu_extraction_batch 1
--   menu_board 1 | menu_category 31 | menu_board_category 31
--   canonical_dish up to 380 | menu_item 387 | menu_item_source 387
--   menu_item_variant 393 | menu_item_price 380 (13 variants have no
--   legible price -> no price row) | menu_item_price_source 380 | menu_board_item 387
--
-- CONVENTIONS / JUDGEMENT CALLS
--  1. Categories: the JSON nests two ways - STARTERS has true nested sub-blocks (INDIAN,
--     CHINESE) and SNACKS instead marks its two columns with a flat "subcategory" string
--     (PIZZA, SANDWICH) with no items of its own. Both are modeled the same way: the parent
--     heading gets its own menu_category row (even though SNACKS carries no items directly)
--     and each child's parent_category_id points to it. "CHICKEN DISHES" and "SANDWICH" each
--     print twice, in unrelated parts of the menu - both get their own separate category rows
--     (one per JSON section), never merged.
--  2. Splitting: this JSON already gives most portion and protein splits as an explicit
--     "prices" array on one item. Full/Half pairs (6) stay one menu_item with two variants,
--     names kept exactly as printed including the redundant "(Full / Half)" suffix already in
--     the source text. VEG./CHICKEN pairs (7, all in SOUPS + one Chinese Bhel) become two
--     separate menu_item rows sharing a split_group_key, classification taken directly from
--     the split label rather than re-derived from the (identical, protein-neutral) name text.
--     Five more "prices" pairs are neither of these - "Tandoori Roti"/"Tandoori Butter Roti",
--     "Tandoori Naan"/"Tandoori Butter Naan", "Tandoori Paratha"/"Tandoori Butter Paratha",
--     "Dal Fry"/"Dal Fry with Butter", "Bread Butter"/"Toast Butter" - these are genuinely
--     different, separately-orderable dishes sharing one printed line, not sizes of one dish,
--     so each becomes its OWN menu_item named by its own label text, not a variant.
--  3. A single price with a "/" in the name ("Brain Plain Fry / Brain Egg Fry", "Paneer Chilli
--     Dry / Paneer Manchurian Dry *New") is kept as ONE item with the compound name verbatim -
--     there is only one price to assign, so nothing here is split (the same standing rule used
--     for a single-priced "/" name in an earlier restaurant's menu).
--  4. food_classification_code comes from a definitional word in the item's own name
--     (chicken/mutton/fish/prawn/egg, or a vegetable/legume/dairy word), a "Non Veg."/"Veg."
--     qualifier read as a phrase (so "Non Veg. Thali" is non_veg, not veg, despite containing
--     the word VEG), a small set of dishes that are vegetarian by their own definition (plain
--     rice, plain buttered bread/toast, a chutney-and-noodles side - none of these has a
--     meat-based version), or, failing all of that, a vegetarian-only category heading
--     (breads, the "SUBZZIYAAN - VEGETABLE" section, salads/raita/papad, juices, shakes,
--     kulfi/ice-cream, desserts, tea/coffee, cold drinks). It is NULL for 9 items
--     with none of this evidence (mostly a bare "Mix" with no veg or protein word of its own,
--     and one bare "Kheema" with no protein qualifier). "Brain" dishes and the two "Non Veg."
--     items are non_veg with protein_type_id left NULL (the animal/meat is not stated).
--     is_jain / is_vegan / is_eggless / spice_level are NULL everywhere - nothing in the JSON
--     asserts them, and this menu has no GST/tax text anywhere either, so all tax_* columns on
--     menu_item_price are NULL too.
--  5. Canonical dishes: exact-normalized-name match, 380 distinct dishes. No two items
--     print the same name under two different leaf categories anywhere in this menu (checked
--     directly), so every item links except where a protein-split pair (note 2) shares one
--     canonical dish between its two variants, same as a portion-variant pair would.
--  6. Prices: "Sl.Rate" (13 ice-cream items) -> is_market_price = TRUE, price_amount NULL. A
--     blank price (13 items, mostly a "/"-separated pair of names with neither one priced, plus
--     4 standalone drink/kulfi lines) -> no menu_item_price row at all for that item, flagged.
--     No rate-effective date is printed anywhere, so effective_from uses the extraction
--     timestamp for every price row.
--  7. Delivery: "FREE HOME DELIVERY (Minimum order should be Rs. 350/-)" names no third-party
--     platform - this is the restaurant's own delivery, so restaurant_delivery.self_delivery_
--     available = TRUE with self_delivery_min_order_amount = 350, and no delivery_provider link
--     is created (there is nothing to match it to).
--  8. Cuisines: "DELICIOUS FOR: Tandoori, Moghlai, Punjabi, Chinese" matches four platform_tag
--     rows that already exist in the lookup data by exactly these codes (cuisine_tandoori,
--     cuisine_moghlai, cuisine_punjabi, cuisine_chinese) - read by tag_code and linked via
--     restaurant_tag, not re-created. The same line's other items (snacks, fruit juices, milk
--     shake, falooda, ice cream) are dish categories already represented by menu_category, not
--     further cuisine tags.
--  9. Hours: the JSON's own "timing" field says "8:00 am to 12:00 pm", applied to every day of
--     the week (restaurant.veg_nonveg_status, phones etc. are otherwise unaffected by this).
--     That is almost certainly not the restaurant's real hours - a 4-hour morning-only window
--     is implausible for a full-menu restaurant with a dinner-oriented Chinese/tandoori/biryani
--     card - and it directly conflicts with the menu's own "PLEASE NOTE" that the hotel closes
--     "Every Friday between 1 pm to 2 pm" (a break that could not occur inside an 8am-12pm day).
--     Loaded exactly as printed rather than guessed at; menu_item_availability is not populated,
--     since nothing ties a specific dish to a specific day or time window on this menu.
-- 10. Two prices (Chicken Seekh Kabab Rs.160, Veg. Sunlight Spl. Pizza Rs.180) are noted in the
--     JSON as confirmed from a handwritten correction on the physical menu - both are already
--     the values stored here; this is provenance only, not a discrepancy to resolve.
-- 11. Not loaded (no schema column, and/or not itemized in the JSON): HALAL, "NO BEEF", "NO
--     BRANCH", "Family A/C Hall"; the spicy/green-gravy icon legend (the menu states the icons
--     exist but the OCR did not capture which specific items carry each one, so no
--     menu_item_tag rows were created for either); "We Accept All Bank Credit & Debit Card";
--     "Extra Schezwan Sauce or Fry Noodles Rs.30/- Extra" (this simply explains the price of
--     the already-loaded "Extra Schezwan Chutney/Fry Noodles" menu item - not a separate
--     add-on); the menu designer's own printed contact number. See the trailing notes.
-- =====================================================================

--\connect "KhaustanRestaurantMenu"
\set ON_ERROR_STOP on

BEGIN;

-- ---------------------------------------------------------------------
-- 0. Helper sequence (non-mandatory standalone IDs only) + PRE-FLIGHT
-- ---------------------------------------------------------------------
DO $seq$
DECLARE
    v_max BIGINT;
BEGIN
    SELECT GREATEST(
        COALESCE((SELECT MAX(restaurant_phone_id) FROM restaurant_phone), 0),
        COALESCE((SELECT MAX(restaurant_hours_id) FROM restaurant_hours), 0),
        COALESCE((SELECT MAX(restaurant_tag_id) FROM restaurant_tag), 0),
        COALESCE((SELECT MAX(extraction_batch_id) FROM menu_extraction_batch), 0),
        COALESCE((SELECT MAX(canonical_dish_id) FROM canonical_dish), 0),
        COALESCE((SELECT MAX(canonical_dish_name_id) FROM canonical_dish_name), 0)
    ) INTO v_max;
    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS khaustan_sunlight_helper_seq START WITH %s', v_max + 1);
END
$seq$;

DO $pre$
DECLARE
    v_missing text;
BEGIN
    SELECT string_agg(m.item, ', ' ORDER BY m.item)
      INTO v_missing
      FROM (
            SELECT 'protein_type.' || t.code AS item
              FROM (VALUES ('CHICKEN'), ('MUTTON'), ('SEAFOOD'), ('EGG')) AS t(code)
             WHERE NOT EXISTS (SELECT 1 FROM protein_type p WHERE p.code = t.code)
            UNION ALL
            SELECT 'platform_tag.' || t.code
              FROM (VALUES ('cuisine_tandoori'), ('cuisine_moghlai'), ('cuisine_punjabi'), ('cuisine_chinese')) AS t(code)
             WHERE NOT EXISTS (SELECT 1 FROM platform_tag g WHERE g.tag_code = t.code)
           ) AS m;

    IF v_missing IS NOT NULL THEN
        RAISE EXCEPTION 'Hotel Sunlight load aborted - lookup rows missing: %. Run the lookup seed script first.', v_missing;
    END IF;

    IF EXISTS (SELECT 1 FROM menu_item WHERE restaurant_id = 400070012)
       OR EXISTS (SELECT 1 FROM menu_extraction_batch WHERE restaurant_id = 400070012)
       OR EXISTS (SELECT 1 FROM source_record WHERE source_id = 400070012) THEN
        RAISE EXCEPTION 'Hotel Sunlight (restaurant_id 400070012) already has menu data or source_id 400070012 is in use - refusing to load twice.';
    END IF;

    IF EXISTS (SELECT 1 FROM establishment WHERE establishment_id = 400070012)
       OR EXISTS (SELECT 1 FROM restaurant WHERE restaurant_id = 400070012) THEN
        RAISE EXCEPTION 'establishment_id/restaurant_id 400070012 is already in use by a different row - resolve before loading.';
    END IF;
END
$pre$;

